local events = CreateFrame("Frame")
for _, e in ipairs({ "PLAYER_LOGIN", "ADDON_LOADED", "TRAINER_SHOW", "TRAINER_UPDATE", "MERCHANT_SHOW" }) do
	events:RegisterEvent(e)
end
events:SetScript("OnEvent", function(_, event, arg1)
	if event == "ADDON_LOADED" then
		if arg1 == "Blizzard_TrainerUI" then HookTrainer() end
	elseif event == "PLAYER_LOGIN" then
		HookTrainer()
	elseif event == "TRAINER_SHOW" or event == "TRAINER_UPDATE" then
		if event == "TRAINER_SHOW" and CraftPlan.RememberTrainer then CraftPlan.RememberTrainer() end
		HookTrainer()
		UpdateTrainer()
	elseif event == "MERCHANT_SHOW" then
		local list = BuyList()
		if #list > 0 then buyButton:Enable() else buyButton:Disable() end
		if #SellList() > 0 then sellButton:Enable() else sellButton:Disable() end
	end
end)
end)()

----------------------------------------------------------------------------------------------
-- Пункт в меню Questie «Торговцы рецептами для CraftPlan»: торговцы, у которых продаются
-- рецепты ваших профессий, которых у вас ещё нет. Какие предметы — рецепты: русское название
-- из базы Questie («Рецепт: копченый шалфокунь») сверяется с таблицей CraftPlanThresholds.
-- База Questie большая — перебираем её один раз за сессию, понемногу за кадр, чтобы не было рывка
;(function()
local KEY = "Торговцы рецептами для CraftPlan"
local ICON = "Interface\\Icons\\INV_Scroll_03"
local PER_FRAME = 1500 -- предметов базы за кадр
local MAX_LINES = 12   -- рецептов в подсказке к торговцу

local function DB()
	CraftPlanDB = CraftPlanDB or {}
	CraftPlanDB.profs = CraftPlanDB.profs or {}
	return CraftPlanDB
end

local SKILL_ID = {
	["Кузнечное дело"] = 164, ["Кожевничество"] = 165, ["Алхимия"] = 171, ["Кулинария"] = 185,
	["Горное дело"] = 186, ["Портняжное дело"] = 197, ["Инженерное дело"] = 202, ["Наложение чар"] = 333,
	["Ювелирное дело"] = 755, ["Начертание"] = 773, ["Первая помощь"] = 129,
}

local function RankOf(prof)
	for i = 1, GetNumSkillLines() do
		local name, isHeader, _, rank = GetSkillLineInfo(i)
		if not isHeader and name == prof then return rank end
	end
end

-- Строчные буквы и «е» вместо «ё»: в базе Questie «Рецепт: копченый шалфокунь»,
-- а в игре «Копченый шалфокунь». string.lower русские буквы не трогает
local function Norm(str)
	str = str:gsub("\208\129", "\208\149"):gsub("\209\145", "\208\181")
	str = str:gsub("\208([\144-\159])", function(c) return "\208" .. string.char(c:byte() + 32) end)
	str = str:gsub("\208([\160-\175])", function(c) return "\209" .. string.char(c:byte() - 32) end)
	return str:lower()
end

local recipes      -- после перебора: список { item, prof, name }
local scanning
local lastSig

local function Update()
	if not recipes then return end
	if not (Questie and Questie.db and Questie.db.char and Questie.db.char.vendorList and QuestieLoader) then return end
	local Townsfolk = QuestieLoader:ImportModule("Townsfolk")
	local QuestieDB = QuestieLoader:ImportModule("QuestieDB")
	local QuestieMenu = QuestieLoader:ImportModule("QuestieMenu")
	local QuestieMap = QuestieLoader:ImportModule("QuestieMap")
	if not (Townsfolk and Townsfolk.PopulateVendors and QuestieDB) then return end

	-- какие рецепты нужны: профессия есть, рецепт не изучен (если окно профессии открывали)
	local db, want, sigParts = DB(), {}, {}
	local ranks = {}
	for _, r in ipairs(recipes) do
		if ranks[r.prof] == nil then ranks[r.prof] = RankOf(r.prof) or false end
		if ranks[r.prof] then
			local p = db.profs[r.prof]
			local known = false
			if p and p.scanned then
				for _, rec in ipairs(p.recipes) do
					if rec.name == r.name then known = true break end
				end
			end
			if not known then
				want[#want + 1] = r
				sigParts[#sigParts + 1] = r.item
			end
		end
	end
	local sig = table.concat(sigParts, ",")
	if sig == lastSig and Questie.db.char.vendorList[KEY] then return end

	-- торговец -> какие из этих рецептов у него продаются (фракцию проверяет Questie)
	local byNpc, list = {}, {}
	for _, r in ipairs(want) do
		local ok, set = pcall(Townsfolk.PopulateVendors, Townsfolk, { r.item }, {})
		for npc in pairs(ok and set or {}) do -- ошибка в данных одного торговца не ломает весь список
			if not byNpc[npc] then
				byNpc[npc] = {}
				list[#list + 1] = npc
			end
			table.insert(byNpc[npc], r)
		end
	end
	lastSig = sig
	local old = Questie.db.char.vendorList[KEY] or {}
	Questie.db.char.vendorList[KEY] = list
	if QuestieMenu and QuestieMenu.private and QuestieMenu.private.townsfolk_texturemap then
		QuestieMenu.private.townsfolk_texturemap[KEY] = ICON
	end
	-- пункт включён — перерисовать значки; в подсказке — какие рецепты у него есть
	local cfg = Questie.db.profile and Questie.db.profile.townsfolkConfig
	if cfg and cfg[KEY] and QuestieMap and QuestieMap.ShowNPC then
		for _, id in ipairs(old) do QuestieMap:UnloadManualFrames(id, KEY) end
		for _, id in ipairs(list) do
			local name = QuestieDB.QueryNPCSingle(id, "name") or "?"
			local body = {}
			for i, r in ipairs(byNpc[id]) do
				if i > MAX_LINES then
					body[#body + 1] = { "и ещё " .. (#byNpc[id] - MAX_LINES), "" }
					break
				end
				body[#body + 1] = { r.name, r.prof }
			end
			QuestieMap:ShowNPC(id, ICON, 1.2, "|cffffffff" .. name .. "|r", body, true, KEY, true)
		end
	end
end
CraftPlan.UpdateRecipeVendors = Update

-- Подсказка к материалу: где выучить ещё не изученный рецепт — у учителя (с какого навыка и за
-- сколько, если окно учителя открывали) или рецепт-предмет: у каких торговцев вашей фракции и с
-- какого навыка. Торговцы и навык запоминаются по предмету на сессию
local byName, vendorCache, reqTip, reqMiss = nil, {}, nil, {}
local function VendorsOf(item)
	if vendorCache[item] then return vendorCache[item] end
	local Townsfolk = QuestieLoader and QuestieLoader:ImportModule("Townsfolk")
	local QuestieDB = QuestieLoader and QuestieLoader:ImportModule("QuestieDB")
	local TrackerUtils = QuestieLoader and QuestieLoader:ImportModule("TrackerUtils")
	local list = {}
	local ok, set = false, nil
	if Townsfolk and Townsfolk.PopulateVendors then ok, set = pcall(Townsfolk.PopulateVendors, Townsfolk, { item }, {}) end
	local faction = (UnitFactionGroup("player") == "Horde") and "H" or "A"
	for npc in pairs(ok and set or {}) do
		local f = QuestieDB.QueryNPCSingle(npc, "friendlyToFaction")
		if f and f:find(faction, 1, true) then
			local zone, area1, spot
			for area, pts in pairs(QuestieDB.QueryNPCSingle(npc, "spawns") or {}) do
				zone = TrackerUtils and TrackerUtils.GetZoneNameByID and TrackerUtils:GetZoneNameByID(area)
				area1, spot = area, pts[1]
				break
			end
			local name = QuestieDB.QueryNPCSingle(npc, "name") or "?"
			list[#list + 1] = { text = name .. (zone and (" (" .. zone .. ")") or ""), name = name, area = area1, spot = spot }
		end
	end
	table.sort(list, function(a, b) return a.text < b.text end)
	vendorCache[item] = list
	return list
end
-- С какого навыка учится рецепт-предмет: «Требуется: Кулинария (125)» в его подсказке
local function BookReq(item, prof)
	local db = DB()
	db.bookReq = db.bookReq or {}
	if db.bookReq[item] or reqMiss[item] then return db.bookReq[item] end
	reqMiss[item] = GetItemInfo(item) ~= nil -- нет в кэше игры — спросим ещё раз, когда придёт
	reqTip = reqTip or CreateFrame("GameTooltip", "CraftPlanRecipeSrcTip", UIParent, "GameTooltipTemplate")
	reqTip:SetOwner(UIParent, "ANCHOR_NONE")
	reqTip:SetHyperlink("item:" .. item)
	for i = 2, reqTip:NumLines() do
		local fs = _G["CraftPlanRecipeSrcTipTextLeft" .. i]
		local text = fs and fs:GetText()
		local n = text and text:find(prof, 1, true) and tonumber(text:match("%((%d+)%)"))
		if n then db.bookReq[item] = n break end
	end
	reqTip:Hide()
	return db.bookReq[item]
end
function CraftPlan.RecipeSourceText(prof, name)
	local learn = DB().learn and DB().learn[SKILL_ID[prof]]
	local t = learn and learn[name]
	if t then
		return "у учителя профессии, с навыка " .. t.req .. (t.cost > 0 and (", " .. Money(t.cost)) or "")
	end
	if recipes and not byName then
		byName = {}
		for _, r in ipairs(recipes) do byName[r.prof .. "|" .. Norm(r.name)] = r end
	end
	local r = byName and byName[prof .. "|" .. Norm(name)]
	if r then
		local req = BookReq(r.item, prof)
		local itemName = GetItemInfo(r.item) or "рецепт"
		local vendors = VendorsOf(r.item)
		local from = req and (", с навыка " .. req) or ""
		if #vendors == 0 then
			return itemName .. from .. " — у торговцев вашей фракции не продаётся (добыча, квест или репутация)"
		end
		local shown = {}
		for i = 1, math.min(2, #vendors) do shown[i] = vendors[i].text end
		return itemName .. from .. " — продаёт: " .. table.concat(shown, ", ") .. (#vendors > 2 and (" и ещё " .. (#vendors - 2)) or "")
	end
	if learn then return "у учителя нет (возможно, рецепт с добычи или квеста)" end
	if not recipes then return nil end -- база Questie ещё перебирается
	return "скорее всего у учителя — откройте его окно, чтобы узнать с какого навыка"
end

-- Ctrl+щелчок по материалу (сумки, ссылка в чате; Alt+щелчок в Linux Mint забирает оконный менеджер): путь TomTom к торговцу рецептом, для которого
-- нужен этот материал и который вы ещё не изучили. Сначала торговец в вашей зоне
local SKILL_OF = {}
for prof, id in pairs(SKILL_ID) do SKILL_OF[id] = prof end
local function WantedRecipeItems(itemID)
	local uses = CraftPlanReagents and CraftPlanReagents[itemID]
	local list, db = {}, DB()
	if not (uses and recipes) then return list end
	if not byName then CraftPlan.RecipeSourceText("", "") end -- построить byName
	for i = 1, #uses, 2 do
		local prof, recName = SKILL_OF[uses[i]], uses[i + 1]
		local r = prof and RankOf(prof) and byName[prof .. "|" .. Norm(recName)]
		local p = r and db.profs[prof]
		local known = false
		for _, rec in ipairs(p and p.scanned and p.recipes or {}) do
			if rec.name == recName then known = true break end
		end
		-- серый при вашем навыке — навыка не даст, путь к нему не нужен
		local y, g = Thresholds(prof or "", recName)
		local grey = r and y and g and RankOf(prof) >= g
		if r and not known and not grey then list[#list + 1] = r end
	end
	return list
end
CraftPlan.RecipeVendorHint = function(itemID) return #WantedRecipeItems(itemID) > 0 end
local function WaypointToVendor(link)
	local itemID = tonumber(link:match("item:(%d+)"))
	if not itemID then return end
	local here
	local ZoneDB = QuestieLoader and QuestieLoader:ImportModule("ZoneDB")
	local ui = QuestieCompat and QuestieCompat.C_Map and QuestieCompat.C_Map.GetBestMapForUnit("player")
	if ZoneDB and ui then here = ZoneDB:GetAreaIdByUiMapId(ui) end
	local best, bestR
	for _, r in ipairs(WantedRecipeItems(itemID)) do
		for _, v in ipairs(VendorsOf(r.item)) do
			if v.area and v.spot and (not best or (v.area == here and best.area ~= here)) then best, bestR = v, r end
		end
	end
	if not best then return end
	local TrackerUtils = QuestieLoader and QuestieLoader:ImportModule("TrackerUtils")
	if not (TomTom and TrackerUtils and TrackerUtils.SetTomTomTarget) then
		Print("нужны TomTom и Questie, чтобы поставить путь.")
		return
	end
	local title = best.name .. " — " .. (GetItemInfo(bestR.item) or bestR.name)
	TrackerUtils:SetTomTomTarget(title, best.area, best.spot[1], best.spot[2])
	Print("путь TomTom: " .. best.text .. ", рецепт " .. (GetItemInfo(bestR.item) or bestR.name) .. ".")
end
hooksecurefunc("HandleModifiedItemClick", function(link)
	-- материалы не надеваются, поэтому Ctrl+щелчок (примерка) им ничего не делает
	if link and IsControlKeyDown() and not IsShiftKeyDown() and not IsAltKeyDown() then pcall(WaypointToVendor, link) end
end)

-- Перебор базы Questie: имена «Префикс: рецепт», которые есть в таблице порогов
local function StartScan()
	if recipes or scanning or not CraftPlanThresholds then return end
	local QuestieDB = QuestieLoader and QuestieLoader:ImportModule("QuestieDB")
	local ptrs = QuestieDB and QuestieDB.ItemPointers
	if not (ptrs and QuestieDB.QueryItemSingle) then return end
	scanning = true
	local byName = {} -- нормализованное название -> { профессия, название как в игре }
	for prof, id in pairs(SKILL_ID) do
		for name in pairs(CraftPlanThresholds[id] or {}) do byName[Norm(name)] = { prof, name } end
	end
	local found, key = {}, nil
	local f = CreateFrame("Frame")
	f:SetScript("OnUpdate", function(self)
		for _ = 1, PER_FRAME do
			key = next(ptrs, key)
			if not key then
				self:SetScript("OnUpdate", nil)
				recipes, scanning = found, false
				CraftPlan.recipeItems = found -- нужен маршруту прокачки
				Update()
				return
			end
			local name = QuestieDB.QueryItemSingle(key, "name")
			local pre, rec
			if name then pre, rec = name:match("^([^:]+):%s*(.+)$") end
			local hit = rec and byName[Norm(rec)]
			-- «Формула чар для нагрудника: мана I» — это «Чары для нагрудника - мана I»
			local part = not hit and pre and pre:match("^Формула чар для (.+)$")
			if part then hit = byName[Norm("Чары для " .. part .. " - " .. rec)] end
			if hit then found[#found + 1] = { item = key, prof = hit[1], name = hit[2] } end
		end
	end)
end

-- Questie собирает базу после входа — начинаем чуть позже и повторяем, пока не получится
local waitFrame, waited = CreateFrame("Frame"), 0
waitFrame:SetScript("OnUpdate", function(self, elapsed)
	waited = waited + elapsed
	if waited < 5 then return end
	waited = 0
	StartScan()
	if recipes or scanning then self:SetScript("OnUpdate", nil) end
end)
end)()

----------------------------------------------------------------------------------------------
-- Маршрут прокачки до потолка навыка для вашего уровня (вкладка «План»): по каждой профессии — какие рецепты делать на каждом
-- отрезке навыка, что выучить (у учителя или купить рецепт у торговца) и что собрать или купить.
-- Рецепты, пороги цвета и материалы — CraftPlanRouteData (из файлов клиента, в конце файла).
-- С какого навыка рецепт учится, клиент не знает: аддон записывает это в окне учителя профессии
-- (все строки, в том числе «недоступные»). Пока учителя профессии не открывали, считается, что
-- рецепт учится с жёлтого порога (то есть оранжевым не бывает) — маршрут предварительный.
-- Выбор: на каждом очке навыка — рецепт с наименьшей ценой очка (материалы / шанс роста навыка),
-- смена рецепта стоит дополнительно (выучить, новые материалы), поэтому отрезки длинные.
;(function()
local MAX_SKILL = 450
local MIN_CHANCE = 0.34 -- рецепты с меньшим шансом роста навыка не берём
local MARGIN = 1.2      -- материалы для созданий «с шансом» — с запасом
-- Потолки навыка и уровень персонажа, с которого учитель обычно их даёт
local TIERS = { { 75, 5 }, { 150, 10 }, { 225, 20 }, { 300, 35 }, { 375, 50 }, { 450, 65 } }
-- Цель маршрута — самый высокий потолок, который учитель даст на вашем уровне; и следующий за ним
local function LevelCap(level)
	local cap, nextT = TIERS[1][1], nil
	for _, t in ipairs(TIERS) do
		if t[2] <= level then cap = t[1] elseif not nextT then nextT = t end
	end
	return cap, nextT
end
local GATHER = {
	["Горное дело"] = { kind = "Mining", db = "GatherMateMineDB", icon = "Interface\\Icons\\Trade_Mining", verb = "Копать" },
	["Травничество"] = { kind = "Herb Gathering", db = "GatherMateHerbDB", icon = "Interface\\Icons\\Trade_Herbalism", verb = "Собирать" },
}
-- Цена штуки материала по источнику (условные усилия: купить проще, чем выбить с мобов)
local COST = { vendor = 1, ore = 2, object = 2.5, fish = 3, mob = 3, gem = 4, ah = 6, craft = 0.3 }
local KIND_ORDER = { ore = 1, object = 2, mob = 3, fish = 4, gem = 5, vendor = 6, ah = 7 }

-- Камни копаются из жил вместе с рудой (в базе Questie у них вместо жил сундуки и сотни мобов).
-- Номера жил GatherMate, как в ORE_NODES. В ORE_NODES не кладём: там жила — одна руда (фильтр жил)
local STONE_NODES = {
	[2835] = { 201 },                -- грубый камень: медь
	[2836] = { 202, 204, 209 },      -- крупный камень: олово, серебро
	[2838] = { 203, 205, 210 },      -- тяжелый камень: железо, золото
	[7912] = { 206, 207, 208, 211 }, -- твердый камень: мифрил, истинное серебро
	[12365] = { 212, 213, 214, 215 }, -- массивный камень: торий
}
-- Жилы, из которых копается предмет (руда или камень), или nil
local function MinedNodes(id) return ORE_NODES[id] or STONE_NODES[id] end
-- Зоны жил предмета: руда — как в плане (OreZones), камень — по его жилам
local function MinedZones(id)
	if ORE_NODES[id] then return OreZones(id) end
	local nodes = STONE_NODES[id]
	if not (nodes and GatherMate and GatherMate.zoneData and GatherMateMineDB) then return nil end
	local set = {}
	for _, n in ipairs(nodes) do set[n] = true end
	local list, seen = {}, {}
	for zoneName, zd in pairs(GatherMate.zoneData) do
		local db = zd[3] and GatherMateMineDB[zd[3]]
		if db and not seen[zd[3]] then
			seen[zd[3]] = true
			local c = 0
			for _, nodeID in pairs(db) do
				if set[nodeID] then c = c + 1 end
			end
			if c > 0 then list[#list + 1] = { zoneName, c } end
		end
	end
	table.sort(list, function(a, b) return a[2] > b[2] end)
	return list
end

-- Мобы для фарма — не выше вашего уровня + MOB_LEVEL_UP (по наименьшему уровню моба в базе Questie)
local MOB_LEVEL_UP = 5
local function MobFits(q, npc)
	local ok, lvl = pcall(q.QueryNPCSingle, npc, "minLevel")
	return ok and lvl and lvl <= UnitLevel("player") + MOB_LEVEL_UP
end

-- Места сбора — жилы, травы, косяки рыбы, облака газа, а не сундуки, ящики и прочие контейнеры:
-- из них материал не нафармить. Узел GatherMate (по названию, без учёта регистра) — место сбора;
-- остальные объекты Questie — если в названии нет слов-контейнеров (названия трав у Questie и
-- GatherMate иногда расходятся: «Жизнекорень» и «Корень жизни»)
local function Lower(str)
	str = str:gsub("\208\129", "\209\145")
	str = str:gsub("\208([\144-\159])", function(c) return "\208" .. string.char(c:byte() + 32) end)
	str = str:gsub("\208([\160-\175])", function(c) return "\209" .. string.char(c:byte() - 32) end)
	return str:lower()
end
local gatherNames
local GATHER_TYPES = { "Mining", "Herb Gathering", "Fishing", "Extract Gas" }
local CONTAINER_WORDS = { "сундук", "ящик", "сейф", "бочк", "бочон", "мешок", "кулек", "кулёк", "корзин", "тайник", "ларец", "шкатулк",
	"chest", "crate", "box", "barrel", "sack", "cache", "strongbox" }
local function GatherObjects(q, list)
	if not list then return nil end
	if not gatherNames then
		gatherNames = {}
		local ids = GatherMate and GatherMate.nodeIDs
		for _, t in ipairs(GATHER_TYPES) do
			for name in pairs(ids and ids[t] or {}) do gatherNames[Lower(name)] = true end
		end
	end
	local out = {}
	for _, obj in pairs(list) do
		local ok, name = pcall(q.QueryObjectSingle, obj, "name")
		local good = false
		if ok and name then
			name = Lower(name)
			good = gatherNames[name] == true
			if not good then
				good = true
				for _, w in ipairs(CONTAINER_WORDS) do
					if name:find(w, 1, true) then good = false break end
				end
			end
		end
		if good then out[#out + 1] = obj end
	end
	return out
end

local function QDB()
	local q = QuestieLoader and QuestieLoader:ImportModule("QuestieDB")
	if q and q.QueryItemSingle then return q end
end

local function ItemName(id)
	local name = GetItemInfo(id)
	if name then return name end
	local q = QDB()
	local ok, n = false, nil
	if q then ok, n = pcall(q.QueryItemSingle, id, "name") end
	return (ok and n) or ("предмет " .. id)
end

-- Рецепты профессии из таблицы: { spell, name, y, g, acq, item, made, cd, reag = { {id, count} } }
local parsed = {}
local function Recipes(sk)
	if parsed[sk] then return parsed[sk] end
	local list = {}
	for _, line in ipairs(CraftPlanRouteData and CraftPlanRouteData[sk] or {}) do
		local spell, name, y, g, acq, item, made, reag, cd = strsplit("|", line)
		local rec = { spell = tonumber(spell), name = name, y = tonumber(y), g = tonumber(g), acq = (acq == "1"),
			item = tonumber(item), made = tonumber(made) or 1, cd = (cd == "1"), reag = {} }
		for id, c in reag:gmatch("(%d+)%*(%d+)") do rec.reag[#rec.reag + 1] = { id = tonumber(id), count = tonumber(c) } end
		list[#list + 1] = rec
	end
	parsed[sk] = list
	return list
end

-- Шанс роста навыка: оранжевый — всегда, дальше убывает до серого порога (правило 3.3.5)
local function Chance(y, g, r)
	if r < y then return 1 end
	if r >= g or g <= y then return 0 end
	return (g - r) / (g - y)
end

local function SkillLines()
	local t = {}
	for i = 1, GetNumSkillLines() do
		local name, isHeader, _, rank, _, _, max = GetSkillLineInfo(i)
		if name and not isHeader then t[name] = { rank = rank, max = max } end
	end
	return t
end

-- Изученные рецепты (если окно профессии открывали)
local function KnownSet(prof)
	local p = DB().profs[prof]
	if not (p and p.scanned) then return nil end
	local set = {}
	for _, rec in ipairs(p.recipes) do set[rec.name] = true end
	return set
end

